// ContactUs.js
import React, { useState } from 'react';
import { Container, Row, Col, Form, Button, Alert } from 'react-bootstrap';
import './ContactUs.css';

const ContactUs = () => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });
    const [showAlert, setShowAlert] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        // Simulação de envio (substitua por sua API)
        setTimeout(() => {
            console.log('Dados do formulário:', formData);
            setIsSubmitting(false);
            setShowAlert(true);
            setFormData({
                name: '',
                email: '',
                subject: '',
                message: ''
            });

            // Esconder alerta após 5 segundos
            setTimeout(() => setShowAlert(false), 5000);
        }, 1000);
    };

    const contactInfo = [
        {
            icon: 'bx bx-map',
            title: 'Localização',
            content: 'São Paulo, Brasil',
            link: '#'
        },
        {
            icon: 'bx bx-envelope',
            title: 'Email',
            content: 'seuemail@example.com',
            link: 'mailto:seuemail@example.com'
        },
        {
            icon: 'bx bx-phone',
            title: 'Telefone',
            content: '+55 (11) 99999-9999',
            link: 'tel:+5511999999999'
        },
        {
            icon: 'bx bx-share-alt',
            title: 'Redes Sociais',
            content: 'Conecte-se comigo',
            social: true
        }
    ];

    const socialLinks = [
        {
            icon: 'bx bxl-linkedin',
            url: '#',
            name: 'LinkedIn'
        },
        {
            icon: 'bx bxl-github',
            url: '#',
            name: 'GitHub'
        },
        {
            icon: 'bx bxl-instagram',
            url: '#',
            name: 'Instagram'
        },
        {
            icon: 'bx bxl-whatsapp',
            url: '#',
            name: 'WhatsApp'
        }
    ];

    return (
        <section id="contact" className="contact section-bg">
            <Container>
                <div className="section-title">
                    <h2>Contato</h2>
                    <p>Entre em contato comigo para discutir oportunidades, projetos ou colaborações.</p>
                </div>

                <Row>
                    {/* Informações de Contato */}
                    <Col lg={5} className="d-flex align-items-stretch">
                        <div className="info">
                            {contactInfo.map((item, index) => (
                                <div key={index} className="address">
                                    <i className={item.icon}></i>
                                    <h4>{item.title}:</h4>
                                    {item.social ? (
                                        <div className="social-links">
                                            {socialLinks.map((social, socialIndex) => (
                                                <a
                                                    key={socialIndex}
                                                    href={social.url}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    title={social.name}
                                                >
                                                    <i className={social.icon}></i>
                                                </a>
                                            ))}
                                        </div>
                                    ) : (
                                        <p>
                                            {item.link ? (
                                                <a href={item.link}>{item.content}</a>
                                            ) : (
                                                item.content
                                            )}
                                        </p>
                                    )}
                                </div>
                            ))}
                        </div>
                    </Col>

                    {/* Formulário de Contato */}
                    <Col lg={7} className="mt-5 mt-lg-0 d-flex align-items-stretch">
                        <Form onSubmit={handleSubmit} className="php-email-form">
                            {showAlert && (
                                <Alert variant="success" className="alert-success">
                                    <i className="bx bx-check-circle"></i>
                                    Sua mensagem foi enviada com sucesso! Obrigado.
                                </Alert>
                            )}

                            <Row>
                                <Col md={6} className="form-group">
                                    <Form.Label htmlFor="name">Seu Nome</Form.Label>
                                    <Form.Control
                                        type="text"
                                        name="name"
                                        id="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                        required
                                        placeholder="Digite seu nome completo"
                                    />
                                </Col>
                                <Col md={6} className="form-group mt-3 mt-md-0">
                                    <Form.Label htmlFor="email">Seu Email</Form.Label>
                                    <Form.Control
                                        type="email"
                                        name="email"
                                        id="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                        placeholder="seu.email@exemplo.com"
                                    />
                                </Col>
                            </Row>

                            <div className="form-group mt-3">
                                <Form.Label htmlFor="subject">Assunto</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="subject"
                                    id="subject"
                                    value={formData.subject}
                                    onChange={handleChange}
                                    required
                                    placeholder="Assunto da mensagem"
                                />
                            </div>

                            <div className="form-group mt-3">
                                <Form.Label htmlFor="message">Mensagem</Form.Label>
                                <Form.Control
                                    as="textarea"
                                    rows="6"
                                    name="message"
                                    id="message"
                                    value={formData.message}
                                    onChange={handleChange}
                                    required
                                    placeholder="Descreva sua mensagem aqui..."
                                />
                            </div>

                            <div className="text-center mt-4">
                                <Button
                                    type="submit"
                                    className="contact-btn"
                                    disabled={isSubmitting}
                                >
                                    {isSubmitting ? (
                                        <>
                                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                            Enviando...
                                        </>
                                    ) : (
                                        <>
                                            <i className="bx bx-send me-2"></i>
                                            Enviar Mensagem
                                        </>
                                    )}
                                </Button>
                            </div>
                        </Form>
                    </Col>
                </Row>
            </Container>
        </section>
    );
};

export default ContactUs;
